		"Cancelled · {x} back": ["Annulé · {x} remboursés", "Cancelado · {x} devueltos", "Annullato · {x} rimborsati", "בוטל · {x} הוחזרו"],
		" · {x} lost": [" · {x} perdus", " · {x} perdidos", " · {x} persi", " · {x} אבדו"],
